import{_ as o,o as a,c as u,a2 as q}from"./chunks/framework.DnrXFDHb.js";const d=JSON.parse('{"title":"分布式算力深度拆解：GPU上墙与中国方舱","description":"","frontmatter":{"title":"分布式算力深度拆解：GPU上墙与中国方舱","updated":"2026-08-22T00:00:00.000Z","visibility":"public"},"headers":[],"relativePath":"算电协同/分布式算力深度拆解_GPU上墙与中国方舱.md","filePath":"算电协同/分布式算力深度拆解_GPU上墙与中国方舱.md","lastUpdated":null}'),r={name:"算电协同/分布式算力深度拆解_GPU上墙与中国方舱.md"};function l(e,t,p,i,n,s){return a(),u("div",null,[...t[0]||(t[0]=[q('<h1 id="发布信息" tabindex="-1">发布信息 <a class="header-anchor" href="#发布信息" aria-label="Permalink to &quot;发布信息&quot;">​</a></h1><p><strong>推荐标题（TOP1）</strong>：英伟达把16块GPU挂上民宅外墙：不是送算力，是买电</p><p><strong>备选标题（TOP2/TOP3）</strong>：</p><ul><li>美国的GPU上了墙，中国的算力进了方舱：分布式算力的两条路线</li><li>分布式算力十年：谁掌握末端电力冗余，谁就多一条供给曲线</li></ul><p><strong>摘要（118字）</strong>：英伟达联手SPAN把16块Blackwell GPU挂上美国民宅外墙，表面是送算力，实质是买电力冗余。这套模式搬不到中国的民宅，但&quot;算力向负荷末端下沉&quot;的方向已经成立——在中国，它的形态不是上墙，是进园区、进楼宇、进方舱。</p><p><strong>封面建议</strong>：左半边为美国独栋住宅外墙挂着空调大小的白色计算箱（XFRA渲染图风格），右半边为中国产业园区里的预制化算力方舱，中间一条电力线连接，标题压字&quot;算力下沉&quot;。</p><hr><h1 id="正文" tabindex="-1">正文 <a class="header-anchor" href="#正文" aria-label="Permalink to &quot;正文&quot;">​</a></h1><p>上个月，一条新闻在算力圈里刷了屏：英伟达要把价值25万美元的计算设备，免费挂到美国普通老百姓家的外墙上。</p><p>事情的轮廓大概是这样的。今年4月13日，旧金山一家做智能配电箱的公司SPAN发布了一个叫XFRA的产品——一个空调外机大小的白色金属箱，里面塞着16块液冷的英伟达RTX PRO 6000 Blackwell服务器版GPU、4个AMD EPYC处理器和3TB内存，单箱功率约19.2千瓦（来源：SPAN官方公告及DataCenterDynamics报道，2026年4月）。英伟达是最初的技术合作方，美国最大的住宅建筑商之一PulteGroup负责在新房社区里落地。三季度先在美国西南部试点100户，SPAN自己放出的目标是：2027年做到8万个节点、超过1吉瓦的分布式算力（来源：Ars Technica，2026年5月）。</p><p>房主的待遇听上去相当诱人：设备零元安装，电费和网费有人补贴，还能分到算力收益。</p><p>但先纠正一个普遍误读——这不是&quot;英伟达提出的分布式算力计划&quot;。公告是SPAN发的，英伟达的角色是供卡和站台。三方各取所需：SPAN拿到了算力入口，PulteGroup拿到了新房卖点，英伟达拿到了一样东西。</p><p>这一样东西，才是理解整件事的钥匙。</p><h2 id="英伟达看上的不是你家的墙-是你家电表箱里睡着的冗余" tabindex="-1">英伟达看上的不是你家的墙，是你家电表箱里睡着的冗余 <a class="header-anchor" href="#英伟达看上的不是你家的墙-是你家电表箱里睡着的冗余" aria-label="Permalink to &quot;英伟达看上的不是你家的墙，是你家电表箱里睡着的冗余&quot;">​</a></h2><p>英伟达全球能源行业高级董事总经理Marc Spieler对CNBC说了一句大实话：&quot;我们想拿到电。电网上现在有很多电力，但要为大型数据中心在单一地点凑出大负荷，已经很难了。利用那些已经接入电力的地方，非常合理。&quot;（来源：CNBC，2026年5月）</p><p>这句话得掰开看。美国独栋住宅标配200安培的入户服务，折合功率大约48千瓦，但普通家庭日常实际只用1到3千瓦——SPAN的测算口径是，美国家庭平均只用到入户容量的40%左右（来源：SPAN CEO Arch Rao接受Realtor.com采访，2026年5月）。换句话说，每一户的美国家庭，都有一块&quot;已并网、已付费、但没被任何人定价&quot;的电力冗余。</p><p>干过地产的人听到这里应该立刻反应过来这是什么。这就像一栋写字楼，房产证上只有一万平米，但实际报批的市政配套容量是按一万五配的——多出来的五千平米的&quot;配套冗余&quot;，过去躺在那里不产生任何价值，现在有人想出了一种办法把它租出去。XFRA干的就是这件事：把千家万户配电容量里的&quot;赠送面积&quot;聚合起来，变成可以卖钱的算力。</p><p>再看它要绕开的东西有多贵。美国一座传统的100兆瓦数据中心，从选址到通电通常要三到五年，每兆瓦建设成本在1500万美元上下；更要命的是并网——美国电网的新增并网申请排队规模已经超过2600吉瓦，大量项目卡在队列里动弹不得（来源：行业统计，口径含发电与负荷项目）。而SPAN声称，装8000个XFRA节点就能顶一座100兆瓦数据中心，部署速度快6倍、成本只有五分之一。这组数字目前没有第三方验证，我倾向于把它当作&quot;方向性宣言&quot;而不是工程结论——但它指向的痛点是真的：算力行业扩张的上限，已经不是芯片，也不是资本，而是电力并网的速度。</p><p><strong>算力的尽头不是芯片，是并网点；并网点的尽头，是千家万户的电表箱。</strong></p><p>这才是英伟达愿意站台的原因。芯片卖出去只是第一步，让每一块芯片尽快找到电、找到墙、找到网线，才算把生意做完。</p><h2 id="为什么是现在-推理正在把算力拉回负荷中心" tabindex="-1">为什么是现在：推理正在把算力拉回负荷中心 <a class="header-anchor" href="#为什么是现在-推理正在把算力拉回负荷中心" aria-label="Permalink to &quot;为什么是现在：推理正在把算力拉回负荷中心&quot;">​</a></h2><p>XFRA这类模式能成立，底层是一个更大的结构变化：算力需求的主力，正在从训练切换到推理。</p><p>训练和推理对选址的要求完全不同。训练是&quot;批发&quot;——一次性把几万张卡集中起来跑几个月，它不在乎离用户多远，只在乎电便不便宜，所以训练集群可以塞进内蒙古、贵州、宁夏的戈壁和山沟里。推理是&quot;零售&quot;——用户每问一次问题、每生成一张图、每调用一次智能体，都是一次实时请求，时延敏感、并发极高、全天候运转。便利店可以开在郊区仓库里吗？不行，它必须开在人流旁边。</p><p>数据正在验证这个切换。中国信通院《2026年中国人工智能算力发展白皮书》显示，2025年国内大模型推理算力占比首次超过训练，达到52%，预计2026年升至60%（来源：中国信通院，2026年）。TrendForce的口径更激进：北美五大云厂商2026年推理算力投入预计增长122%，是训练侧增速（56%）的两倍多（来源：TrendForce，转引自21世纪经济报道，2026年5月）。国家数据局监测的日均Token调用量，从2024年初的约1000亿涨到2026年3月的140万亿以上——两年，一千多倍。</p><p>IDC预测，到2029年推理将占中国算力需求的近八成。</p><p>这个趋势对基础设施的含义非常直接：**推理占比越高，算力就越要贴着人口和产业密集区部署。**而人口和产业密集区，恰恰是新建大型数据中心最难获批的地方。需求和供给在地理上拧着——这个拧巴，就是分布式算力存在的全部理由。</p><h2 id="泼一盆冷水-gpu上墙这套-搬到中国会死" tabindex="-1">泼一盆冷水：GPU上墙这套，搬到中国会死 <a class="header-anchor" href="#泼一盆冷水-gpu上墙这套-搬到中国会死" aria-label="Permalink to &quot;泼一盆冷水：GPU上墙这套，搬到中国会死&quot;">​</a></h2><p>看到这条新闻，国内已经有朋友在问：这个模式能不能抄？</p><p>我的判断很明确：**照抄&quot;民宅上墙&quot;，必死。**三道墙挡在前面。</p><p>第一道是容量墙。美国独栋住宅入户48千瓦、只用四成，才有近20千瓦的冗余可卖。中国城镇居民住宅的户均配电容量，按住宅电气设计规范的配置口径，一般在几千瓦到十几千瓦这个量级（【推断】，各地标准不一，此处为区间估算），一台柜式空调加几台电器就吃掉大半，根本挤不出一个19.2千瓦的计算箱。</p><p>第二道是电价墙。XFRA的经济账成立，前提是美国居民电价不低、且电网公司愿意为&quot;盘活存量容量&quot;付钱。中国居民电价长期享受交叉补贴，是全球主要经济体里最低的一档，电网没有动力为居民侧的零碎容量付费，房主也分不到什么钱。</p><p>第三道是产权墙。美国的独栋住宅，外墙和院子是私人的，挂个箱子跟装空调一样简单。中国的城市居民住的是高层公寓，外墙属于全体业主共有，你往上面挂一个19千瓦、24小时运转的设备试试——物业、业委会、消防、住建，任何一关都过不去。</p><p>所以，如果你的结论是&quot;分布式算力在中国没戏&quot;，那你犯了一个典型的错误：**把形态当成了方向。**上墙是形态，下沉是方向。真正要回答的问题是——在中国，&quot;负荷末端的电力冗余&quot;藏在哪儿？</p><h2 id="中国版的答案-不在民宅墙上-在工商业末端" tabindex="-1">中国版的答案：不在民宅墙上，在工商业末端 <a class="header-anchor" href="#中国版的答案-不在民宅墙上-在工商业末端" aria-label="Permalink to &quot;中国版的答案：不在民宅墙上，在工商业末端&quot;">​</a></h2><p>我的答案：在园区里，在楼宇里，在那些被能耗指标卡得喘不过气的一线城市里。</p><p>先看北京、上海、深圳、杭州这类城市的共性。它们同时具有三个特征，而这三个特征正好拼出分布式算力的生存空间。</p><p>其一，能耗指标紧到骨子里。北京已经从今年起对PUE高于1.35的存量数据中心征收差别电价，超限额一倍以内每度电加价0.2元，一倍以上加价0.5元（来源：《北京市存量数据中心优化工作方案（2024—2027年）》，2024年11月印发）。上海新建数据中心的PUE硬门槛压到1.25，还在酝酿进一步收紧，并且明确在研究跟进差别电价（来源：解放日报，2026年1月）。在这些城市，新建大型数据中心的能评指标，基本是有钱也买不到的稀缺品。</p><p>其二，电力容量存在结构性闲置。一线城市的大量产业园区、写字楼、存量老机房，配电容量按十年前的标准报装，实际负载率不高——这是中国版的&quot;赠送面积&quot;，只不过它不在民宅电表箱里，而在工商业用户的变压器里。</p><p>其三，推理需求最密集。金融、电商、游戏、智驾、政务，推理请求最旺的地方就是这些城市。需求在城里，指标卡死在城里，冗余也躺在城里——三件事凑齐，生意就成立了。</p><p>政策也在往这个方向引。工信部等六部门早在2023年的《算力基础设施高质量发展行动计划》里就提出&quot;加速边缘算力协同部署&quot;；今年4月国务院《关于推进服务业扩能提质的意见》明确要求&quot;有序推进算力布局与边缘算力建设&quot;；6月，国家数据局把边缘算力列入下一步聚焦的四大方向（来源：公开政策文件）。地方层面，上海每年发放10亿元&quot;算力券&quot;激活需求侧，浙江&quot;十五五&quot;数字经济规划征求意见稿写进了&quot;按需建设边缘算力节点&quot;。工信部在今年7月的国新办发布会上，把布局口径明确为&quot;枢纽—区域—边缘&quot;的梯次协同——注意，&quot;边缘&quot;已经进入官方表述的第三级（来源：工信部，2026年7月20日）。</p><p>用地产的话说：民宅上墙是散铺，产权碎、管理难、没人流；园区和楼宇里的分布式节点是统一业权的购物中心——容量集中、产权清晰、有专业物管。美国人没得选才去啃散铺，中国有现成的购物中心，为什么要去啃散铺？</p><h2 id="方舱-把数据中心从-工程-变成-产品" tabindex="-1">方舱：把数据中心从&quot;工程&quot;变成&quot;产品&quot; <a class="header-anchor" href="#方舱-把数据中心从-工程-变成-产品" aria-label="Permalink to &quot;方舱：把数据中心从&quot;工程&quot;变成&quot;产品&quot;&quot;">​</a></h2><p>形态问题解决之后，下一个问题是交付：分布式算力节点用什么装？</p><p>行业给出的答案越来越统一——预制化、模块化，也就是业内说的&quot;算力方舱&quot;。</p><p>看三个信号。2025年4月，电力设备巨头伊顿（Eaton）砸14亿美元收购了美国预集成模块化电源机房制造商Fibrebond，目标就是缩短AI数据中心的交付周期。2025年6月，施耐德电气推出预制的EcoStruxure Pod数据中心，整柜集成配电、液冷和高密度机架，单模块支持1兆瓦以上的AI集群。2026年6月，台达在COMPUTEX上发布预制式AI模块化数据中心，官方口径是把部署时间最多缩短60%（来源：Fortune Business Insights行业综述及各公司公告，2025—2026年）。北美模块化数据中心市场2024年的规模约104亿美元，仍在两位数增长。</p><p>这组信号说明一件事：**数据中心正在经历一场&quot;装配式建筑化&quot;。**干过工程的都知道，现浇改预制意味着什么——工期从年缩到月，质量从&quot;看施工队水平&quot;变成&quot;看工厂品控&quot;，最重要的是，资产从&quot;一次性定制的工程&quot;变成了&quot;可批量复制、可快速部署的标准产品&quot;。</p><p>方舱在一线城市的应用场景，我数得出至少五个：园区电力扩容等不起大机房，先落几个方舱抢时间；北京差别电价逼退的老旧小机房，用高效率方舱原位替代；酒店、医院、商业综合体的闲置配电站房，改造成边缘推理节点；重大活动和临时项目要的应急算力；以及和分布式光伏、储能打包的&quot;光储算&quot;一体化节点。</p><p>这里面藏着一层更深的资产逻辑。传统数据中心是&quot;重不动产&quot;——土建一投，三十年动弹不得。方舱是&quot;可移动的产能&quot;——今天放在上海张江服务智驾推理，明天需求变了可以吊装到苏州的工厂园区。我在地产行业干了20年，太清楚&quot;可移动&quot;三个字对资产残值意味着什么了：固定物业的残值押注区位，可移动产能的残值押注需求——而在算力这个行业，需求迁移的速度远快于区位变迁。</p><p>江浙沪恰好是这门生意最顺的落点：全球最完整的液冷、电源、集装箱制造供应链在这里，最密的推理需求在这里，最活跃的电力现货和需求响应市场也在这里。制造、需求、电价弹性，三样东西在同一个半径里凑齐的情况，全国找不出第二个。</p><h2 id="下半张牌-方舱不只是算力资产-还是电力资产" tabindex="-1">下半张牌：方舱不只是算力资产，还是电力资产 <a class="header-anchor" href="#下半张牌-方舱不只是算力资产-还是电力资产" aria-label="Permalink to &quot;下半张牌：方舱不只是算力资产，还是电力资产&quot;">​</a></h2><p>如果只把方舱理解成&quot;缩小版机房&quot;，那就把这门生意看小了一半。</p><p>今年上半年发生了一件标志性的事：中国联通韶关数据中心、中国移动广州和湛江数据中心，以虚拟电厂聚合的形式首次参与电力现货交易——电价低的时候多跑算力任务&quot;吃进&quot;低价电，晚高峰电价冲高时压减非紧急任务给电网让路（来源：中国工业新闻网、电子工程专辑，2026年5—6月）。再往前，去年7月上海已经做过一次更科幻的验证：浦东用电高峰时段，中国电信临港智算中心把正在运行的AI任务在3分钟内转移到湖北十堰的数据中心，完成了全国首次算力跨区域转移响应（来源：国网上海电力相关测试通报，2025年7月）。</p><p>这就是&quot;算随电动&quot;。国家能源局的数据是，截至2025年底全国虚拟电厂项目已达470个，经测试的最大调节能力1685万千瓦，一年增长约70%（来源：国家能源局例行发布会，2026年4月）。自然资源保护协会（NRDC）的专家给过一个量级：单一大型数据中心的可调负荷可达10到50兆瓦。</p><p>把这两件事接到方舱上，逻辑就通了。一个分布式算力节点，白天卖推理算力赚一份钱；电网紧张时，靠自带的储能和可中断任务参与需求响应，再赚一份钱；夜间低谷电价时满负荷跑可延迟任务，把度电成本压到最低。<strong>单向买电的机房是成本项，双向调度的方舱是资产项——这是我从地产转行看电力交易这几年，见到的最像&quot;租金+增值&quot;双轮模型的新物种。</strong></p><p>就像当年我们做商业地产，好物业赚的不只是租金，还有资产升值；未来的分布式算力节点，赚的不只是算力服务费，还有电力市场的灵活性收益。这份收益现在还是零头，但随着现货市场全面铺开，它会从零头变成利润表上正经的一行。</p><h2 id="未来3到5年-以及10年-我的三个判断" tabindex="-1">未来3到5年，以及10年：我的三个判断 <a class="header-anchor" href="#未来3到5年-以及10年-我的三个判断" aria-label="Permalink to &quot;未来3到5年，以及10年：我的三个判断&quot;">​</a></h2><p>把上面的碎片拼起来，给出我对这个赛道的时间表判断。</p><p>**未来3到5年（2026—2030），是分布式算力从&quot;概念验证&quot;走向&quot;规模商用&quot;的窗口期。**推理占比会从现在的六成左右走向八成（IDC口径），一线城市的边缘算力节点会从政策文件里的名词变成批量落地的项目；方舱和预制化模块会成为分布式算力的标准交付形态，就像今天光伏行业的组件一样标准化；算电协同会从联通、移动的那几个试点，变成所有新建算力项目的标配能力。格局上，运营商、云厂商和专业化第三方会形成三分天下——前两者握需求和通道，第三方的机会在&quot;制造+投建+运营&quot;的一体化交付。想在牌桌上留位置，卡位期就是2026到2028这三年：等能耗指标进一步收紧、现货市场全面铺开后，后进者连入场券都拿不到。</p><p>**未来10年（到2035年前后），算力会变成像今天冷链、充电桩一样的城市配套。**楼宇即节点，园区即电厂，&quot;集中式做训练、分布式做推理&quot;会成为默认架构，算力按&quot;批发价&quot;和&quot;零售价&quot;分层定价。到那个时候回看，XFRA挂在墙上的那个白箱子，大概会被记入教科书——不是因为它多成功，而是因为它是算力行业第一次公开承认：电在哪里，算力就得去哪里。</p><p>当然，三个真实的不确定性必须摆在桌面上。一是端侧芯片的能效跃升——如果手机和汽车本地就能消化大部分推理，边缘节点的需求会被分流；二是国产芯片的供给节奏——方舱里装什么芯，直接决定单舱经济性；三是电力市场改革的速度——虚拟电厂收益兑现的前提是现货和需求响应机制真正跑通。这三条任何一条不及预期，上面的时间表都得往后挪。</p><p>最后一个问题，留给正在看这篇文章的决策者：当算力的扩张逻辑从&quot;拿更大的地、并更大的网&quot;变成&quot;聚合更碎的容量、贴更近的需求&quot;，你手里的资产——不管是园区、楼宇还是制造产能——距离这张新的供给曲线，还有几步？</p><hr><h1 id="数据来源" tabindex="-1">数据来源 <a class="header-anchor" href="#数据来源" aria-label="Permalink to &quot;数据来源&quot;">​</a></h1><p>[1] SPAN官方公告及DataCenterDynamics/Ars Technica/CNBC/Realtor.com报道（2026年4—5月）｜XFRA产品形态、节点配置、成本对比、美国住宅电力冗余口径 [2] 中国信通院《2026年中国人工智能算力发展白皮书》（2026年）｜推理算力占比52%首超训练 [3] 工业和信息化部国新办新闻发布会（2026-07-20）｜我国智能算力规模2185 EFLOPS（FP16口径）、&quot;枢纽—区域—边缘&quot;梯次布局 [4] 《北京市存量数据中心优化工作方案（2024—2027年）》（2024-11）及解放日报报道（2026-01）｜京沪数据中心PUE约束与差别电价 [5] 国家能源局例行发布会（2026-04）及中国工业新闻网（2026-06）｜虚拟电厂规模与数据中心参与电力现货交易</p><p>⚠️ 风险提示：端侧推理芯片替代、电力市场改革节奏不及预期。本文仅作产业研究，不构成任何投资建议。</p><p>关注「算电协同研习社」，看这个判断会不会兑现。</p><hr><h1 id="金句-可直接做海报-切片文案" tabindex="-1">金句（可直接做海报/切片文案） <a class="header-anchor" href="#金句-可直接做海报-切片文案" aria-label="Permalink to &quot;金句（可直接做海报/切片文案）&quot;">​</a></h1><ol><li><strong>英伟达看上的不是你家的墙，是你家电表箱里睡着的冗余。</strong></li><li><strong>算力的尽头不是芯片，是并网点；并网点的尽头，是千家万户的电表箱。</strong></li><li><strong>训练是批发，可以塞进戈壁；推理是零售，必须开在人流旁边。</strong></li><li><strong>照抄&quot;GPU上墙&quot;必死——上墙是形态，下沉是方向。</strong></li><li><strong>中国的&quot;电力赠送面积&quot;不在民宅电表箱里，在工商业用户的变压器里。</strong></li><li><strong>数据中心正在经历一场&quot;装配式建筑化&quot;：资产从一次性定制的工程，变成可批量复制的标准产品。</strong></li><li><strong>单向买电的机房是成本项，双向调度的方舱是资产项。</strong></li><li><strong>电在哪里，算力就得去哪里。</strong></li></ol><h1 id="图表建议" tabindex="-1">图表建议 <a class="header-anchor" href="#图表建议" aria-label="Permalink to &quot;图表建议&quot;">​</a></h1><ol><li><strong>一张对比图</strong>：传统100MW集中式数据中心 vs 8000个XFRA分布式节点——建设周期、单位成本、并网方式三栏对比（回答：分布式到底省在哪）。标注&quot;SPAN口径，未经第三方验证&quot;。</li><li><strong>一张趋势图</strong>：中国算力需求中训练/推理占比变化（2023—2029E，信通院与IDC口径并列标注）（回答：为什么推理把算力拉回负荷中心）。</li><li><strong>一张地图</strong>：北上深杭四城&quot;能耗约束—电力冗余—推理需求&quot;三要素标注（回答：分布式算力为什么在一线城市成立）。</li><li><strong>一张机制图</strong>：方舱的双重收益结构——算力服务费＋电力市场灵活性收益（回答：方舱为什么是&quot;资产&quot;不是&quot;成本&quot;）。</li></ol><h1 id="其他标题备选-供a-b测试" tabindex="-1">其他标题备选（供A/B测试） <a class="header-anchor" href="#其他标题备选-供a-b测试" aria-label="Permalink to &quot;其他标题备选（供A/B测试）&quot;">​</a></h1><ul><li>40%的住宅电力容量在睡觉，英伟达盯上了它（数据型）</li><li>8000户人家等于一座100MW数据中心？这笔账成立吗（悬念型）</li><li>分布式算力的本质不是技术，是电力冗余的重新定价（观点型）</li><li>为什么GPU上墙在中国行不通，方舱却可以（问题型）</li><li>集中式智算中心之外，第二条供给曲线出现了（产业型）</li><li>美国缺电逼出了&quot;上墙算力&quot;，中国的答案长什么样（地缘对比型）</li><li>19.2千瓦：挂在墙上的一个数字，正在改写算力供给方式（数字+判断型）</li><li>当算力变成&quot;可调负荷&quot;：分布式节点的资产逻辑重估（投资型）</li><li>算力，开始下沉（极简型）</li></ul>',73)])])}const P=o(r,[["render",l]]);export{d as __pageData,P as default};
